package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Object that exposes a single Retrofit instance configured to consume the Ragnarok API.
 * This way all collaborators (repositories, tests) reuse the same
 * base configuration without duplicating code.
 */
object NetworkModule {

    // For Android emulator: 10.0.2.2 points to the host's localhost (your PC)
    // For physical device: use your PC's IP on the network (e.g. 192.168.1.42)
    private const val BASE_URL = "http://64.176.16.51:8000/api/v1/"

    /**
     * Retrofit is created lazily to not initialize the network until it's actually
     * needed. GsonConverterFactory handles mapping JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Object that exposes a single Retrofit instance configured to consume the Ragnarok API.
 * This way all collaborators (repositories, tests) reuse the same
 * base configuration without duplicating code.
 */
object NetworkModule {

    // For Android emulator: 10.0.2.2 points to the host's localhost (your PC)
    // For physical device: use your PC's IP on the network (e.g. 192.168.1.42)
    private const val BASE_URL = "http://64.176.16.51:8000/api/v1/"

    /**
     * Returns the base URL for API endpoints (includes /api/v1/)
     */
    internal const val API_BASE_URL = BASE_URL

    /**
     * Returns the base URL for images (without /api/v1/)
     */
    internal const val IMAGE_BASE_URL = "http://64.176.16.51:8000/api/v1"

    /**
     * Retrofit is created lazily to not initialize the network until it's actually
     * needed. GsonConverterFactory handles mapping JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for the item detail screen.
 * Manages the loading and state of the detailed item information.
 */
class ItemDetailViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<ItemDetailUiState>(ItemDetailUiState.Loading)
    val uiState: StateFlow<ItemDetailUiState> = _uiState.asStateFlow()

    fun loadItemDetail(itemId: Int) {
        viewModelScope.launch {
            _uiState.value = ItemDetailUiState.Loading
            try {
                val item = itemRepository.getItem(itemId)
                _uiState.value = ItemDetailUiState.Success(item)
            } catch (e: Exception) {
                _uiState.value = when {
                    e.message?.contains("404") == true -> ItemDetailUiState.NotFound
                    e.message?.contains("HTTP") == true -> ItemDetailUiState.Error("Network error. Please try again.")
                    else -> ItemDetailUiState.Error(e.message ?: "Unknown error")
                }
            }
        }
    }
}

/**
 * Possible states of the detail screen
 */
sealed class ItemDetailUiState {
    object Loading : ItemDetailUiState()
    object NotFound : ItemDetailUiState()
    data class Success(val item: Item) : ItemDetailUiState()
    data class Error(val message: String) : ItemDetailUiState()
}

package com.example.ragnarokdatabase.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import java.io.File

/**
 * ViewModel for the item detail screen.
 * Manages the loading and state of the detailed item information.
 */
class ItemDetailViewModel(
    private val itemRepository: ItemRepository = ItemRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<ItemDetailUiState>(ItemDetailUiState.Loading)
    val uiState: StateFlow<ItemDetailUiState> = _uiState.asStateFlow()

    private val _uploadState = MutableStateFlow<ImageUploadState>(ImageUploadState.Idle)
    val uploadState: StateFlow<ImageUploadState> = _uploadState.asStateFlow()

    fun loadItemDetail(itemId: Int) {
        viewModelScope.launch {
            _uiState.value = ItemDetailUiState.Loading
            try {
                val item = itemRepository.getItem(itemId)
                _uiState.value = ItemDetailUiState.Success(item)
            } catch (e: Exception) {
                _uiState.value = when {
                    e.message?.contains("404") == true -> ItemDetailUiState.NotFound
                    e.message?.contains("HTTP") == true -> ItemDetailUiState.Error("Network error. Please try again.")
                    else -> ItemDetailUiState.Error(e.message ?: "Unknown error")
                }
            }
        }
    }

    fun uploadCollectionImage(itemId: Int, imageFile: File) {
        viewModelScope.launch {
            _uploadState.value = ImageUploadState.Uploading
            try {
                val updatedItem = itemRepository.uploadCollectionImage(itemId, imageFile)

                // Small delay to ensure the backend has saved the image
                kotlinx.coroutines.delay(500)

                _uploadState.value = ImageUploadState.Success

                // Force reload by fetching the item again
                // This ensures we get fresh data and triggers image reload
                try {
                    val refreshedItem = itemRepository.getItem(itemId)
                    _uiState.value = ItemDetailUiState.Success(refreshedItem)
                } catch (e: Exception) {
                    // If refresh fails, still show success with the updated item
                    _uiState.value = ItemDetailUiState.Success(updatedItem)
                }
            } catch (e: Exception) {
                val errorMessage = when {
                    e.message?.contains("404") == true -> "Item not found"
                    e.message?.contains("HTTP") == true -> "Network error. Please try again."
                    else -> e.message ?: "Unknown error"
                }
                _uploadState.value = ImageUploadState.Error(errorMessage)
            }
        }
    }

    fun resetUploadState() {
        _uploadState.value = ImageUploadState.Idle
    }
}

/**
 * Possible states of the detail screen
 */
sealed class ItemDetailUiState {
    object Loading : ItemDetailUiState()
    object NotFound : ItemDetailUiState()
    data class Success(val item: Item) : ItemDetailUiState()
    data class Error(val message: String) : ItemDetailUiState()
}

/**
 * Possible states of image upload
 */
sealed class ImageUploadState {
    object Idle : ImageUploadState()
    object Uploading : ImageUploadState()
    object Success : ImageUploadState()
    data class Error(val message: String) : ImageUploadState()
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.*
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.runTest
import okhttp3.MultipartBody
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.mockito.Mock
import org.mockito.MockitoAnnotations
import org.mockito.kotlin.any
import org.mockito.kotlin.eq
import org.mockito.kotlin.whenever
import java.io.File

/**
 * Pruebas unitarias para ItemRepository
 */
@OptIn(ExperimentalCoroutinesApi::class)
class ItemRepositoryTest {

    @Mock
    private lateinit var mockApi: RagnarokApiService

    @Mock
    private lateinit var mockFile: File

    private lateinit var repository: ItemRepository

    private lateinit var closeable: AutoCloseable

    @Before
    fun setup() {
        closeable = MockitoAnnotations.openMocks(this)
        repository = ItemRepository(mockApi)
    }

    @Test
    fun `getItem returns item from API`() = runTest {
        // Given
        val expectedItem = createSampleItem(501, "Red Potion")
        whenever(mockApi.getItem(501)).thenReturn(expectedItem)

        // When
        val result = repository.getItem(501)

        // Then
        assertEquals(expectedItem, result)
        assertEquals(501, result.id)
        assertEquals("Red Potion", result.name)
    }

    @Test(expected = Exception::class)
    fun `getItem throws exception when API fails`() = runTest {
        // Given
        whenever(mockApi.getItem(999999)).thenThrow(RuntimeException("404 Not Found"))

        // When
        repository.getItem(999999)

        // Then - exception should be thrown
    }

    @Test
    fun `getPopularItems returns list of popular items`() = runTest {
        // Given
        val popularItems = listOf(
            PopularItem(501, "Red Potion", "Consumable", 100),
            PopularItem(502, "Orange Potion", "Consumable", 80)
        )
        val response = PopularItemsResponse(period = "today", items = popularItems)
        whenever(mockApi.getPopularItems("today", 10)).thenReturn(response)

        // When
        val result = repository.getPopularItems("today", 10)

        // Then
        assertEquals(2, result.size)
        assertEquals("Red Potion", result[0].name)
        assertEquals(100, result[0].viewCount)
    }

    @Test
    fun `getPopularItems with different periods`() = runTest {
        // Given
        val yesterdayItems = listOf(PopularItem(503, "Yellow Potion", "Consumable", 60))
        val response = PopularItemsResponse(period = "yesterday", items = yesterdayItems)
        whenever(mockApi.getPopularItems("yesterday", 10)).thenReturn(response)

        // When
        val result = repository.getPopularItems("yesterday", 10)

        // Then
        assertEquals(1, result.size)
        assertEquals("Yellow Potion", result[0].name)
    }

    @Test
    fun `getPopularItems with custom limit`() = runTest {
        // Given
        val items = (1..20).map {
            PopularItem(it, "Item $it", "Consumable", 100 - it)
        }
        val response = PopularItemsResponse(period = "last7days", items = items)
        whenever(mockApi.getPopularItems("last7days", 20)).thenReturn(response)

        // When
        val result = repository.getPopularItems("last7days", 20)

        // Then
        assertEquals(20, result.size)
    }

    @Test
    fun `searchItems returns list of items`() = runTest {
        // Given
        val items = listOf(
            createSampleItem(501, "Red Potion"),
            createSampleItem(507, "Red Herb")
        )
        whenever(mockApi.searchItems("red", 50)).thenReturn(items)

        // When
        val result = repository.searchItems("red", 50)

        // Then
        assertEquals(2, result.size)
        assertTrue(result.all { it.name.contains("Red", ignoreCase = true) })
    }

    @Test
    fun `searchItems by ID returns single item`() = runTest {
        // Given
        val items = listOf(createSampleItem(501, "Red Potion"))
        whenever(mockApi.searchItems("501", 50)).thenReturn(items)

        // When
        val result = repository.searchItems("501", 50)

        // Then
        assertEquals(1, result.size)
        assertEquals(501, result[0].id)
    }

    @Test
    fun `searchItems returns empty list when no results`() = runTest {
        // Given
        whenever(mockApi.searchItems("nonexistent", 50)).thenReturn(emptyList())

        // When
        val result = repository.searchItems("nonexistent", 50)

        // Then
        assertTrue(result.isEmpty())
    }

    @Test
    fun `uploadCollectionImage returns updated item`() = runTest {
        // Given
        val updatedItem = createSampleItem(501, "Red Potion")
        whenever(mockApi.uploadCollectionImage(eq(501), any())).thenReturn(updatedItem)

        // When
        val result = repository.uploadCollectionImage(501, mockFile)

        // Then
        assertEquals(updatedItem, result)
        assertEquals(501, result.id)
    }

    @Test(expected = Exception::class)
    fun `uploadCollectionImage throws exception on API failure`() = runTest {
        // Given
        whenever(mockApi.uploadCollectionImage(eq(999999), any()))
            .thenThrow(RuntimeException("404 Not Found"))

        // When
        repository.uploadCollectionImage(999999, mockFile)

        // Then - exception should be thrown
    }

    @Test
    fun `getItemCount returns total count`() = runTest {
        // Given
        val countResponse = ItemCountResponse(6169)
        whenever(mockApi.getItemCount()).thenReturn(countResponse)

        // When
        val result = repository.getItemCount()

        // Then
        assertEquals(6169, result)
    }

    @Test
    fun `getItemTypes returns list of types with counts`() = runTest {
        // Given
        val types = listOf(
            ItemType("Weapon", 500),
            ItemType("Armor", 300),
            ItemType("Consumable", 200)
        )
        val response = ItemTypesResponse(totalTypes = 3, types = types)
        whenever(mockApi.getItemTypes()).thenReturn(response)

        // When
        val result = repository.getItemTypes()

        // Then
        assertEquals(3, result.size)
        assertEquals("Weapon", result[0].type)
        assertEquals(500, result[0].count)
    }

    @Test
    fun `getItemTypes returns empty list when no types available`() = runTest {
        // Given
        val response = ItemTypesResponse(totalTypes = 0, types = emptyList())
        whenever(mockApi.getItemTypes()).thenReturn(response)

        // When
        val result = repository.getItemTypes()

        // Then
        assertTrue(result.isEmpty())
    }

    @Test
    fun `filterItemsByType returns filtered items`() = runTest {
        // Given
        val items = listOf(
            createSampleItem(1201, "Knife"),
            createSampleItem(1202, "Sword")
        )
        whenever(mockApi.filterItemsByType("Weapon", 0, 50)).thenReturn(items)

        // When
        val result = repository.filterItemsByType("Weapon", 0, 50)

        // Then
        assertEquals(2, result.size)
        assertTrue(result.all { it.type == "Weapon" })
    }

    @Test
    fun `filterItemsByType with pagination`() = runTest {
        // Given
        val items = listOf(createSampleItem(1251, "Claymore"))
        whenever(mockApi.filterItemsByType("Weapon", 50, 50)).thenReturn(items)

        // When
        val result = repository.filterItemsByType("Weapon", 50, 50)

        // Then
        assertEquals(1, result.size)
    }

    @Test
    fun `filterItemsByType with custom limit`() = runTest {
        // Given
        val items = (1..20).map { createSampleItem(1200 + it, "Weapon $it") }
        whenever(mockApi.filterItemsByType("Weapon", 0, 20)).thenReturn(items)

        // When
        val result = repository.filterItemsByType("Weapon", 0, 20)

        // Then
        assertEquals(20, result.size)
    }

    @Test
    fun `filterItemsByType returns empty list when no items match`() = runTest {
        // Given
        whenever(mockApi.filterItemsByType("InvalidType", 0, 50)).thenReturn(emptyList())

        // When
        val result = repository.filterItemsByType("InvalidType", 0, 50)

        // Then
        assertTrue(result.isEmpty())
    }

    // Helper function
    private fun createSampleItem(id: Int, name: String): Item {
        return Item(
            id = id,
            name = name,
            description = "Test item",
            type = "Weapon",
            subtype = "Sword",
            buyPrice = 1000,
            sellPrice = 500,
            stats = ItemStats(100, null, null, 100, 0),
            requiredLevel = 1,
            requiredJob = null,
            gender = null,
            location = "Right_Hand",
            sprite = "test",
            script = null,
            equipScript = null,
            unequipScript = null
        )
    }
}

package com.example.ragnarokdatabase.model

import org.junit.Assert.*
import org.junit.Test

/**
 * Pruebas unitarias para el modelo Item y sus métodos auxiliares
 */
class ItemTest {

    @Test
    fun `getIconUrl returns correct URL format`() {
        val item = createSampleItem(id = 501)
        val expectedUrl = "http://64.176.16.51:8000/api/v1/items/images/item/501.png"

        val actualUrl = item.getIconUrl()

        assertEquals(expectedUrl, actualUrl)
    }

    @Test
    fun `getCollectionImageUrl returns URL with timestamp`() {
        val item = createSampleItem(id = 502)

        val actualUrl = item.getCollectionImageUrl()

        assertTrue(actualUrl.startsWith("http://64.176.16.51:8000/api/v1/items/images/collection/502.png?t="))
        assertTrue(actualUrl.contains("?t="))
    }

    @Test
    fun `getRequiredJobsText returns comma-separated string when jobs exist`() {
        val item = createSampleItem(requiredJob = listOf("Swordsman", "Knight", "Crusader"))

        val result = item.getRequiredJobsText()

        assertEquals("Swordsman, Knight, Crusader", result)
    }

    @Test
    fun `getRequiredJobsText returns null when no jobs required`() {
        val item = createSampleItem(requiredJob = null)

        val result = item.getRequiredJobsText()

        assertNull(result)
    }

    @Test
    fun `getRequiredJobsText returns empty string when jobs list is empty`() {
        val item = createSampleItem(requiredJob = emptyList())

        val result = item.getRequiredJobsText()

        assertEquals("", result)
    }

    @Test
    fun `item with slots greater than zero should display with slots`() {
        val item = createSampleItem(
            name = "Falchion",
            stats = ItemStats(atk = 39, matk = null, defense = null, weight = 60, slots = 3)
        )

        val slots = item.stats.slots
        val displayName = if (slots > 0) "${item.name} [$slots]" else item.name

        assertEquals("Falchion [3]", displayName)
    }

    @Test
    fun `item with zero slots should not display slots`() {
        val item = createSampleItem(
            name = "Sword",
            stats = ItemStats(atk = 25, matk = null, defense = null, weight = 50, slots = 0)
        )

        val slots = item.stats.slots
        val displayName = if (slots > 0) "${item.name} [$slots]" else item.name

        assertEquals("Sword", displayName)
    }

    @Test
    fun `item stats contains correct values`() {
        val stats = ItemStats(
            atk = 150,
            matk = 120,
            defense = 10,
            weight = 100,
            slots = 2
        )

        assertEquals(150, stats.atk)
        assertEquals(120, stats.matk)
        assertEquals(10, stats.defense)
        assertEquals(100, stats.weight)
        assertEquals(2, stats.slots)
    }

    @Test
    fun `item stats with null values`() {
        val stats = ItemStats(
            atk = null,
            matk = null,
            defense = null,
            weight = 50,
            slots = 0
        )

        assertNull(stats.atk)
        assertNull(stats.matk)
        assertNull(stats.defense)
        assertEquals(50, stats.weight)
        assertEquals(0, stats.slots)
    }

    // Helper function to create sample items
    private fun createSampleItem(
        id: Int = 501,
        name: String = "Red Potion",
        description: String = "A healing potion",
        type: String = "Consumable",
        subtype: String? = "Healing",
        buyPrice: Int = 50,
        sellPrice: Int = 25,
        stats: ItemStats = ItemStats(null, null, null, 10, 0),
        requiredLevel: Int = 1,
        requiredJob: List<String>? = null,
        gender: String? = null,
        location: String? = null,
        sprite: String = "red_potion",
        script: String? = null,
        equipScript: String? = null,
        unequipScript: String? = null
    ): Item {
        return Item(
            id = id,
            name = name,
            description = description,
            type = type,
            subtype = subtype,
            buyPrice = buyPrice,
            sellPrice = sellPrice,
            stats = stats,
            requiredLevel = requiredLevel,
            requiredJob = requiredJob,
            gender = gender,
            location = location,
            sprite = sprite,
            script = script,
            equipScript = equipScript,
            unequipScript = unequipScript
        )
    }
}

package com.example.ragnarokdatabase.utils

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.ItemStats
import org.junit.Assert.*
import org.junit.Test

/**
 * Pruebas unitarias para funciones de utilidad y extensiones
 */
class ItemUtilsTest {

    @Test
    fun `formatItemName with slots appends slot count`() {
        val item = createItem(name = "Falchion", slots = 3)
        val result = formatItemNameWithSlots(item)
        assertEquals("Falchion [3]", result)
    }

    @Test
    fun `formatItemName without slots returns name only`() {
        val item = createItem(name = "Sword", slots = 0)
        val result = formatItemNameWithSlots(item)
        assertEquals("Sword", result)
    }

    @Test
    fun `formatItemName with one slot`() {
        val item = createItem(name = "Stiletto", slots = 1)
        val result = formatItemNameWithSlots(item)
        assertEquals("Stiletto [1]", result)
    }

    @Test
    fun `formatItemName with maximum slots`() {
        val item = createItem(name = "Chain Mail", slots = 4)
        val result = formatItemNameWithSlots(item)
        assertEquals("Chain Mail [4]", result)
    }

    @Test
    fun `hasRequirements returns true when requirements exist`() {
        val item = createItem(
            requiredLevel = 50,
            requiredJob = listOf("Swordsman", "Knight")
        )
        assertTrue(hasRequirements(item))
    }

    @Test
    fun `hasRequirements returns false when level is 0 and no jobs`() {
        val item = createItem(requiredLevel = 0, requiredJob = null)
        assertFalse(hasRequirements(item))
    }

    @Test
    fun `hasRequirements returns false when level is 1 and no jobs`() {
        val item = createItem(requiredLevel = 1, requiredJob = null)
        assertFalse(hasRequirements(item))
    }

    @Test
    fun `hasRequirements returns true when only level requirement exists`() {
        val item = createItem(requiredLevel = 30, requiredJob = null)
        assertTrue(hasRequirements(item))
    }

    @Test
    fun `hasRequirements returns true when only job requirement exists`() {
        val item = createItem(requiredLevel = 1, requiredJob = listOf("Mage"))
        assertTrue(hasRequirements(item))
    }

    @Test
    fun `hasRequirements returns false when job list is empty`() {
        val item = createItem(requiredLevel = 0, requiredJob = emptyList())
        assertFalse(hasRequirements(item))
    }

    @Test
    fun `formatPrice formats buy and sell prices correctly`() {
        assertEquals("1000z", formatPrice(1000))
        assertEquals("50z", formatPrice(50))
        assertEquals("1000000z", formatPrice(1000000))
        assertEquals("0z", formatPrice(0))
    }

    @Test
    fun `formatWeight formats weight correctly`() {
        assertEquals("100", formatWeight(100))
        assertEquals("10", formatWeight(10))
        assertEquals("1", formatWeight(1))
    }

    @Test
    fun `hasStats returns true when item has attack stats`() {
        val item = createItem(atk = 150, matk = null, defense = null)
        assertTrue(hasStats(item))
    }

    @Test
    fun `hasStats returns true when item has matk stats`() {
        val item = createItem(atk = null, matk = 120, defense = null)
        assertTrue(hasStats(item))
    }

    @Test
    fun `hasStats returns true when item has defense stats`() {
        val item = createItem(atk = null, matk = null, defense = 50)
        assertTrue(hasStats(item))
    }

    @Test
    fun `hasStats returns false when item has no combat stats`() {
        val item = createItem(atk = null, matk = null, defense = null)
        assertFalse(hasStats(item))
    }

    @Test
    fun `isEquipment returns true for weapons`() {
        val item = createItem(type = "Weapon", subtype = "Sword")
        assertTrue(isEquipment(item))
    }

    @Test
    fun `isEquipment returns true for armor`() {
        val item = createItem(type = "Armor", subtype = "Headgear")
        assertTrue(isEquipment(item))
    }

    @Test
    fun `isEquipment returns false for consumables`() {
        val item = createItem(type = "Consumable", subtype = "Healing")
        assertFalse(isEquipment(item))
    }

    @Test
    fun `isEquipment returns false for etc items`() {
        val item = createItem(type = "Etc", subtype = null)
        assertFalse(isEquipment(item))
    }

    // Helper functions
    private fun formatItemNameWithSlots(item: Item): String {
        return if (item.stats.slots > 0) {
            "${item.name} [${item.stats.slots}]"
        } else {
            item.name
        }
    }

    private fun hasRequirements(item: Item): Boolean {
        val hasLevelRequirement = item.requiredLevel > 1
        val hasJobRequirement = !item.requiredJob.isNullOrEmpty()
        return hasLevelRequirement || hasJobRequirement
    }

    private fun formatPrice(price: Int): String {
        return "${price}z"
    }

    private fun formatWeight(weight: Int): String {
        return weight.toString()
    }

    private fun hasStats(item: Item): Boolean {
        return item.stats.atk != null || item.stats.matk != null || item.stats.defense != null
    }

    private fun isEquipment(item: Item): Boolean {
        return item.type == "Weapon" || item.type == "Armor"
    }

    private fun createItem(
        id: Int = 1,
        name: String = "Test Item",
        type: String = "Weapon",
        subtype: String? = "Sword",
        requiredLevel: Int = 1,
        requiredJob: List<String>? = null,
        atk: Int? = null,
        matk: Int? = null,
        defense: Int? = null,
        slots: Int = 0
    ): Item {
        return Item(
            id = id,
            name = name,
            description = "Test description",
            type = type,
            subtype = subtype,
            buyPrice = 1000,
            sellPrice = 500,
            stats = ItemStats(atk, matk, defense, 100, slots),
            requiredLevel = requiredLevel,
            requiredJob = requiredJob,
            gender = null,
            location = "Right_Hand",
            sprite = "test",
            script = null,
            equipScript = null,
            unequipScript = null
        )
    }
}

package com.example.ragnarokdatabase.viewmodel

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
import app.cash.turbine.test
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.ItemStats
import com.example.ragnarokdatabase.model.ItemType
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.mockito.Mock
import org.mockito.MockitoAnnotations
import org.mockito.kotlin.whenever

/**
 * Pruebas unitarias para FilterViewModel
 */
@OptIn(ExperimentalCoroutinesApi::class)
class FilterViewModelTest {

    @get:Rule
    val instantExecutorRule = InstantTaskExecutorRule()

    private val testDispatcher = StandardTestDispatcher()

    @Mock
    private lateinit var mockRepository: ItemRepository

    private lateinit var viewModel: FilterViewModel

    private lateinit var closeable: AutoCloseable

    @Before
    fun setup() {
        closeable = MockitoAnnotations.openMocks(this)
        Dispatchers.setMain(testDispatcher)
        viewModel = FilterViewModel(mockRepository)
    }

    @After
    fun tearDown() {
        Dispatchers.resetMain()
        closeable.close()
    }

    @Test
    fun `initial state is Loading`() = runTest {
        viewModel.uiState.test {
            assertTrue(awaitItem() is FilterUiState.Loading)
        }
    }

    @Test
    fun `loadItemsByType returns Success with items`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 100))
        val items = listOf(
            createSampleItem(1201, "Knife"),
            createSampleItem(1202, "Sword")
        )
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(items)

        // When
        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is FilterUiState.Success)
            assertEquals(2, (state as FilterUiState.Success).items.size)
            assertEquals(2, state.totalPages) // 100 items / 50 per page = 2 pages
        }
    }

    @Test
    fun `loadItemsByType with empty results returns Empty state`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 0))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(emptyList())

        // When
        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is FilterUiState.Empty)
            assertEquals("No items found for type: Weapon", (state as FilterUiState.Empty).message)
        }
    }

    @Test
    fun `loadItemsByType with 404 error returns Error state`() = runTest {
        // Given
        whenever(mockRepository.getItemTypes()).thenThrow(RuntimeException("404 Not Found"))

        // When
        viewModel.loadItemsByType("InvalidType", 0)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is FilterUiState.Error)
            assertEquals("Items not found", (state as FilterUiState.Error).message)
        }
    }

    @Test
    fun `loadItemsByType with network error returns Error state`() = runTest {
        // Given
        whenever(mockRepository.getItemTypes()).thenThrow(RuntimeException("HTTP 500 Server Error"))

        // When
        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is FilterUiState.Error)
            assertEquals("Network error. Please try again.", (state as FilterUiState.Error).message)
        }
    }

    @Test
    fun `loadItemsByType updates currentType and currentPage`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Armor", count = 50))
        val items = listOf(createSampleItem(2301, "Cotton Shirt"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Armor", 50, 50)).thenReturn(items)

        // When
        viewModel.loadItemsByType("Armor", 1)
        advanceUntilIdle()

        // Then
        viewModel.currentType.test {
            assertEquals("Armor", awaitItem())
        }
        viewModel.currentPage.test {
            assertEquals(1, awaitItem())
        }
    }

    @Test
    fun `loadItemsByType calculates correct totalPages`() = runTest {
        // Given - 125 items should result in 3 pages (50 items per page)
        val itemTypes = listOf(ItemType(type = "Consumable", count = 125))
        val items = listOf(createSampleItem(501, "Red Potion"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Consumable", 0, 50)).thenReturn(items)

        // When
        viewModel.loadItemsByType("Consumable", 0)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is FilterUiState.Success)
            assertEquals(3, (state as FilterUiState.Success).totalPages)
        }
    }

    @Test
    fun `loadNextPage increments page number`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 150))
        val items1 = listOf(createSampleItem(1201, "Knife"))
        val items2 = listOf(createSampleItem(1202, "Sword"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(items1)
        whenever(mockRepository.filterItemsByType("Weapon", 50, 50)).thenReturn(items2)

        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // When
        viewModel.loadNextPage()
        advanceUntilIdle()

        // Then
        viewModel.currentPage.test {
            assertEquals(1, awaitItem())
        }
    }

    @Test
    fun `loadPreviousPage decrements page number`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 150))
        val items1 = listOf(createSampleItem(1201, "Knife"))
        val items2 = listOf(createSampleItem(1202, "Sword"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 50, 50)).thenReturn(items2)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(items1)

        viewModel.loadItemsByType("Weapon", 1)
        advanceUntilIdle()

        // When
        viewModel.loadPreviousPage()
        advanceUntilIdle()

        // Then
        viewModel.currentPage.test {
            assertEquals(0, awaitItem())
        }
    }

    @Test
    fun `loadPreviousPage does nothing when on first page`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 100))
        val items = listOf(createSampleItem(1201, "Knife"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(items)

        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // When
        viewModel.loadPreviousPage()
        advanceUntilIdle()

        // Then - should stay on page 0
        viewModel.currentPage.test {
            assertEquals(0, awaitItem())
        }
    }

    @Test
    fun `goToPage loads specific page`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 200))
        val items1 = listOf(createSampleItem(1201, "Knife"))
        val items3 = listOf(createSampleItem(1203, "Axe"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Weapon", 0, 50)).thenReturn(items1)
        whenever(mockRepository.filterItemsByType("Weapon", 100, 50)).thenReturn(items3)

        viewModel.loadItemsByType("Weapon", 0)
        advanceUntilIdle()

        // When
        viewModel.goToPage(2)
        advanceUntilIdle()

        // Then
        viewModel.currentPage.test {
            assertEquals(2, awaitItem())
        }
    }

    @Test
    fun `totalItems updates correctly`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Card", count = 300))
        val items = listOf(createSampleItem(4001, "Poring Card"))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Card", 0, 50)).thenReturn(items)

        // When
        viewModel.loadItemsByType("Card", 0)
        advanceUntilIdle()

        // Then
        viewModel.totalItems.test {
            assertEquals(300, awaitItem())
        }
    }

    @Test
    fun `loadItemsByType without matching type sets totalItems to 0`() = runTest {
        // Given
        val itemTypes = listOf(ItemType(type = "Weapon", count = 100))
        whenever(mockRepository.getItemTypes()).thenReturn(itemTypes)
        whenever(mockRepository.filterItemsByType("Armor", 0, 50)).thenReturn(emptyList())

        // When
        viewModel.loadItemsByType("Armor", 0)
        advanceUntilIdle()

        // Then
        viewModel.totalItems.test {
            assertEquals(0, awaitItem())
        }
    }

    // Helper function
    private fun createSampleItem(id: Int, name: String): Item {
        return Item(
            id = id,
            name = name,
            description = "Test item",
            type = "Weapon",
            subtype = "Sword",
            buyPrice = 1000,
            sellPrice = 500,
            stats = ItemStats(100, null, null, 100, 0),
            requiredLevel = 1,
            requiredJob = null,
            gender = null,
            location = "Right_Hand",
            sprite = "test",
            script = null,
            equipScript = null,
            unequipScript = null
        )
    }
}

package com.example.ragnarokdatabase.viewmodel

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
import app.cash.turbine.test
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.ItemStats
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.mockito.Mock
import org.mockito.MockitoAnnotations
import org.mockito.kotlin.any
import org.mockito.kotlin.whenever
import java.io.File

/**
 * Pruebas unitarias para ItemDetailViewModel
 */
@OptIn(ExperimentalCoroutinesApi::class)
class ItemDetailViewModelTest {

    @get:Rule
    val instantExecutorRule = InstantTaskExecutorRule()

    private val testDispatcher = StandardTestDispatcher()

    @Mock
    private lateinit var mockRepository: ItemRepository

    @Mock
    private lateinit var mockFile: File

    private lateinit var viewModel: ItemDetailViewModel

    private lateinit var closeable: AutoCloseable

    @Before
    fun setup() {
        closeable = MockitoAnnotations.openMocks(this)
        Dispatchers.setMain(testDispatcher)
        viewModel = ItemDetailViewModel(mockRepository)
    }

    @After
    fun tearDown() {
        Dispatchers.resetMain()
        closeable.close()
    }

    @Test
    fun `initial state is Loading`() = runTest {
        viewModel.uiState.test {
            assertTrue(awaitItem() is ItemDetailUiState.Loading)
        }
    }

    @Test
    fun `loadItemDetail with valid id returns Success state`() = runTest {
        // Given
        val item = createSampleItem(501, "Red Potion")
        whenever(mockRepository.getItem(501)).thenReturn(item)

        // When
        viewModel.loadItemDetail(501)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is ItemDetailUiState.Success)
            assertEquals("Red Potion", (state as ItemDetailUiState.Success).item.name)
            assertEquals(501, state.item.id)
        }
    }

    @Test
    fun `loadItemDetail with 404 error returns NotFound state`() = runTest {
        // Given
        whenever(mockRepository.getItem(999999))
            .thenThrow(RuntimeException("404 Not Found"))

        // When
        viewModel.loadItemDetail(999999)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            assertTrue(awaitItem() is ItemDetailUiState.NotFound)
        }
    }

    @Test
    fun `loadItemDetail with network error returns Error state`() = runTest {
        // Given
        whenever(mockRepository.getItem(501))
            .thenThrow(RuntimeException("HTTP 500 Server Error"))

        // When
        viewModel.loadItemDetail(501)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is ItemDetailUiState.Error)
            assertEquals("Network error. Please try again.", (state as ItemDetailUiState.Error).message)
        }
    }

    @Test
    fun `loadItemDetail with generic error returns Error state with message`() = runTest {
        // Given
        whenever(mockRepository.getItem(501))
            .thenThrow(RuntimeException("Database error"))

        // When
        viewModel.loadItemDetail(501)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is ItemDetailUiState.Error)
            assertEquals("Database error", (state as ItemDetailUiState.Error).message)
        }
    }

    @Test
    fun `uploadCollectionImage shows Uploading then Success state`() = runTest {
        // Given
        val item = createSampleItem(501, "Red Potion")
        whenever(mockRepository.uploadCollectionImage(501, mockFile)).thenReturn(item)
        whenever(mockRepository.getItem(501)).thenReturn(item)

        // When
        viewModel.uploadState.test {
            assertEquals(ImageUploadState.Idle, awaitItem())

            viewModel.uploadCollectionImage(501, mockFile)

            assertEquals(ImageUploadState.Uploading, awaitItem())

            advanceUntilIdle()

            assertEquals(ImageUploadState.Success, awaitItem())
        }
    }

    @Test
    fun `uploadCollectionImage with 404 error returns Error state`() = runTest {
        // Given
        whenever(mockRepository.uploadCollectionImage(999999, mockFile))
            .thenThrow(RuntimeException("404 Not Found"))

        // When
        viewModel.uploadCollectionImage(999999, mockFile)
        advanceUntilIdle()

        // Then
        viewModel.uploadState.test {
            val state = awaitItem()
            assertTrue(state is ImageUploadState.Error)
            assertEquals("Item not found", (state as ImageUploadState.Error).message)
        }
    }

    @Test
    fun `uploadCollectionImage with network error returns Error state`() = runTest {
        // Given
        whenever(mockRepository.uploadCollectionImage(501, mockFile))
            .thenThrow(RuntimeException("HTTP 500 Server Error"))

        // When
        viewModel.uploadCollectionImage(501, mockFile)
        advanceUntilIdle()

        // Then
        viewModel.uploadState.test {
            val state = awaitItem()
            assertTrue(state is ImageUploadState.Error)
            assertEquals("Network error. Please try again.", (state as ImageUploadState.Error).message)
        }
    }

    @Test
    fun `uploadCollectionImage updates item detail after success`() = runTest {
        // Given
        val originalItem = createSampleItem(501, "Red Potion")
        val updatedItem = createSampleItem(501, "Red Potion Updated")
        whenever(mockRepository.uploadCollectionImage(501, mockFile)).thenReturn(updatedItem)
        whenever(mockRepository.getItem(501)).thenReturn(updatedItem)

        // When
        viewModel.uploadCollectionImage(501, mockFile)
        advanceUntilIdle()

        // Then - item detail should be refreshed
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is ItemDetailUiState.Success)
            assertEquals("Red Potion Updated", (state as ItemDetailUiState.Success).item.name)
        }
    }

    @Test
    fun `uploadCollectionImage handles refresh failure gracefully`() = runTest {
        // Given
        val item = createSampleItem(501, "Red Potion")
        whenever(mockRepository.uploadCollectionImage(501, mockFile)).thenReturn(item)
        whenever(mockRepository.getItem(501)).thenThrow(RuntimeException("Refresh failed"))

        // When
        viewModel.uploadCollectionImage(501, mockFile)
        advanceUntilIdle()

        // Then - should still show success with the uploaded item
        viewModel.uploadState.test {
            assertEquals(ImageUploadState.Success, awaitItem())
        }
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is ItemDetailUiState.Success)
            assertEquals("Red Potion", (state as ItemDetailUiState.Success).item.name)
        }
    }

    @Test
    fun `resetUploadState resets to Idle`() = runTest {
        // Given - upload something first
        val item = createSampleItem(501, "Red Potion")
        whenever(mockRepository.uploadCollectionImage(501, mockFile)).thenReturn(item)
        whenever(mockRepository.getItem(501)).thenReturn(item)

        viewModel.uploadCollectionImage(501, mockFile)
        advanceUntilIdle()

        // When
        viewModel.resetUploadState()

        // Then
        viewModel.uploadState.test {
            assertEquals(ImageUploadState.Idle, awaitItem())
        }
    }

    @Test
    fun `loadItemDetail shows Loading state before Success`() = runTest {
        // Given
        val item = createSampleItem(501, "Red Potion")
        whenever(mockRepository.getItem(501)).thenReturn(item)

        // When & Then
        viewModel.uiState.test {
            // Initial state is Loading
            assertTrue(awaitItem() is ItemDetailUiState.Loading)

            viewModel.loadItemDetail(501)

            // Should still be Loading or transition to Loading
            val state1 = awaitItem()
            if (state1 is ItemDetailUiState.Loading) {
                // If still Loading, wait for Success
                advanceUntilIdle()
                val state2 = awaitItem()
                assertTrue(state2 is ItemDetailUiState.Success)
            } else {
                // Already Success
                assertTrue(state1 is ItemDetailUiState.Success)
            }
        }
    }

    // Helper function
    private fun createSampleItem(id: Int, name: String): Item {
        return Item(
            id = id,
            name = name,
            description = "Test item",
            type = "Consumable",
            subtype = "Healing",
            buyPrice = 50,
            sellPrice = 25,
            stats = ItemStats(null, null, null, 10, 0),
            requiredLevel = 1,
            requiredJob = null,
            gender = null,
            location = null,
            sprite = "test",
            script = null,
            equipScript = null,
            unequipScript = null
        )
    }
}

package com.example.ragnarokdatabase.viewmodel

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
import app.cash.turbine.test
import com.example.ragnarokdatabase.data.repository.ItemRepository
import com.example.ragnarokdatabase.model.ItemType
import com.example.ragnarokdatabase.model.PopularItem
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.mockito.Mock
import org.mockito.MockitoAnnotations
import org.mockito.kotlin.whenever

/**
 * Pruebas unitarias para MainViewModel
 */
@OptIn(ExperimentalCoroutinesApi::class)
class MainViewModelTest {

    @get:Rule
    val instantExecutorRule = InstantTaskExecutorRule()

    private val testDispatcher = StandardTestDispatcher()

    @Mock
    private lateinit var mockRepository: ItemRepository

    private lateinit var viewModel: MainViewModel

    private lateinit var closeable: AutoCloseable

    @Before
    fun setup() {
        closeable = MockitoAnnotations.openMocks(this)
        Dispatchers.setMain(testDispatcher)
    }

    @After
    fun tearDown() {
        Dispatchers.resetMain()
        closeable.close()
    }

    @Test
    fun `loadPopularItems emits Loading then Success state`() = runTest {
        // Given
        val popularItems = listOf(
            PopularItem(id = 501, name = "Red Potion", type = "Consumable", viewCount = 100),
            PopularItem(id = 502, name = "Orange Potion", type = "Consumable", viewCount = 80)
        )
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(popularItems)
        whenever(mockRepository.getItemCount()).thenReturn(1000)
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is MainUiState.Success)
            assertEquals(2, (state as MainUiState.Success).items.size)
        }
    }

    @Test
    fun `loadPopularItems emits Error state on exception`() = runTest {
        // Given
        whenever(mockRepository.getPopularItems("today", 10))
            .thenThrow(RuntimeException("Network error"))
        whenever(mockRepository.getItemCount()).thenReturn(1000)
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

