            val state = awaitItem()
            assertTrue(state is MainUiState.Error)
            assertEquals("Network error", (state as MainUiState.Error).message)
        }
    }

    @Test
    fun `loadPopularItems with 404 error shows custom message`() = runTest {
        // Given
        whenever(mockRepository.getPopularItems("yesterday", 10))
            .thenThrow(RuntimeException("404 Not Found"))
        whenever(mockRepository.getItemCount()).thenReturn(1000)
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()
        viewModel.loadPopularItems("yesterday")
        advanceUntilIdle()

        // Then
        viewModel.uiState.test {
            val state = awaitItem()
            assertTrue(state is MainUiState.Error)
            assertEquals("Popular items not found", (state as MainUiState.Error).message)
        }
    }

    @Test
    fun `selectedPeriod updates when loading different period`() = runTest {
        // Given
        val items = listOf(PopularItem(id = 501, name = "Red Potion", type = "Consumable", viewCount = 100))
        whenever(mockRepository.getPopularItems("yesterday", 10)).thenReturn(items)
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(items)
        whenever(mockRepository.getItemCount()).thenReturn(1000)
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

        viewModel.selectedPeriod.test {
            assertEquals("today", awaitItem())

            viewModel.loadPopularItems("yesterday")
            advanceUntilIdle()

            assertEquals("yesterday", awaitItem())
        }
    }

    @Test
    fun `refreshCurrentPeriod reloads with same period`() = runTest {
        // Given
        val items = listOf(PopularItem(id = 501, name = "Red Potion", type = "Consumable", viewCount = 100))
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(items)
        whenever(mockRepository.getItemCount()).thenReturn(1000)
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
