        advanceUntilIdle()
        viewModel.refreshCurrentPeriod()
        advanceUntilIdle()

        // Then
        viewModel.selectedPeriod.test {
            assertEquals("today", awaitItem())
        }
    }

    @Test
    fun `loadTotalItemsCount updates totalItemsCount state`() = runTest {
        // Given
        whenever(mockRepository.getItemCount()).thenReturn(5000)
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(emptyList())
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
