            assertEquals(5000, awaitItem())
        }
    }

    @Test
    fun `loadTotalItemsCount handles error gracefully`() = runTest {
        // Given
        whenever(mockRepository.getItemCount()).thenThrow(RuntimeException("Error"))
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(emptyList())
        whenever(mockRepository.getItemTypes()).thenReturn(emptyList())

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

        // Then
        viewModel.totalItemsCount.test {
            assertNull(awaitItem())
        }
    }

    @Test
    fun `loadItemTypes updates itemTypes state`() = runTest {
        // Given
        val types = listOf(
            ItemType(type = "Weapon", count = 100),
            ItemType(type = "Armor", count = 80)
        )
        whenever(mockRepository.getItemTypes()).thenReturn(types)
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(emptyList())
        whenever(mockRepository.getItemCount()).thenReturn(1000)

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

        // Then
        viewModel.itemTypes.test {
            val result = awaitItem()
            assertEquals(2, result.size)
            assertEquals("Weapon", result[0].type)
            assertEquals(100, result[0].count)
        }
    }

    @Test
    fun `loadItemTypes handles error gracefully`() = runTest {
        // Given
        whenever(mockRepository.getItemTypes()).thenThrow(RuntimeException("Error"))
        whenever(mockRepository.getPopularItems("today", 10)).thenReturn(emptyList())
        whenever(mockRepository.getItemCount()).thenReturn(1000)

        // When
        viewModel = MainViewModel(mockRepository)
        advanceUntilIdle()

        // Then
        viewModel.itemTypes.test {
            assertTrue(awaitItem().isEmpty())
        }
    }
}

